// Normalizza il lead e prepara l'evento per la Conversions API di Meta.
// SHA-256 in JavaScript puro: nessun modulo esterno, funziona anche con i task runner di n8n 2.x.
function sha256(ascii) {
  const bytes = Array.from(new TextEncoder().encode(ascii));
  const K = [], H = [];
  let n = 2, found = 0;
  const isPrime = (x) => { for (let f = 2; f * f <= x; f++) if (x % f === 0) return false; return true; };
  while (found < 64) {
    if (isPrime(n)) {
      if (found < 8) H[found] = (Math.pow(n, 1 / 2) * 2 ** 32) | 0;
      K[found++] = (Math.pow(n, 1 / 3) * 2 ** 32) | 0;
    }
    n++;
  }
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let i = 7; i >= 0; i--) bytes.push(i >= 4 ? 0 : (bitLen >>> (i * 8)) & 0xff);
  const rotr = (v, s) => (v >>> s) | (v << (32 - s));
  for (let off = 0; off < bytes.length; off += 64) {
    const w = new Array(64);
    for (let i = 0; i < 16; i++)
      w[i] = (bytes[off + i * 4] << 24) | (bytes[off + i * 4 + 1] << 16) | (bytes[off + i * 4 + 2] << 8) | bytes[off + i * 4 + 3];
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const t1 = (h + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  return H.map((x) => (x >>> 0).toString(16).padStart(8, '0')).join('');
}
const sha = (v) => (v ? sha256(v) : undefined);
const b = $json.body ?? $json;
const email = String(b.email ?? '').trim().toLowerCase();
let phone = String(b.phone ?? '').replace(/\D/g, '');
if (phone && phone.length <= 10) phone = '39' + phone; // numeri italiani senza prefisso
const [fn, ...rest] = String(b.name ?? '').trim().toLowerCase().split(/\s+/);
const user_data = {
  em: email ? [sha(email)] : undefined,
  ph: phone ? [sha(phone)] : undefined,
  fn: fn ? [sha(fn)] : undefined,
  ln: rest.length ? [sha(rest.join(' '))] : undefined,
  country: [sha('it')],
  client_user_agent: b.user_agent || undefined,
  client_ip_address: $json.headers?.['x-forwarded-for']?.split(',')[0]?.trim() || undefined,
  fbp: b.fbp || undefined,
  fbc: b.fbc || undefined,
};
return [{ json: {
  lead: b,
  marketing_consent: b.marketing_consent === true,
  capi: { data: [{
    event_name: 'Lead',
    event_time: Number(b.event_time) || Math.floor(Date.now() / 1000),
    event_id: b.event_id,
    action_source: 'website',
    event_source_url: b.page_url,
    user_data,
    custom_data: { content_name: b.source },
  }] },
} }];
